const fs = require("node:fs");
const path = require("node:path");

const FULL_GIT_REVISION = /^[0-9a-f]{40}$/i;
const outputPath = path.resolve(
  __dirname,
  "../game/buildSourceRevision.ts",
);
const revision = (
  process.env.EAS_BUILD_GIT_COMMIT_HASH ||
  process.env.EXPO_PUBLIC_SOURCE_REVISION ||
  ""
)
  .trim()
  .toLowerCase();

if (!FULL_GIT_REVISION.test(revision)) {
  throw new Error(
    "EAS qualification builds require a full EAS_BUILD_GIT_COMMIT_HASH or EXPO_PUBLIC_SOURCE_REVISION.",
  );
}

const source = `/**
 * Generated by the EAS post-install hook. Do not edit in build output.
 */
export const BUILD_SOURCE_REVISION: string | null = ${JSON.stringify(revision)};
`;

fs.writeFileSync(outputPath, source, "utf8");
process.stdout.write(`Embedded source revision ${revision}.\n`);
